INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (94980,0,0,0,0,0,0,0,0,'Quite a find you have here. Let\'s see what we can do.',0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (94981,0,0,0,0,0,0,0,0,'Just what we needed.',0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (95663,0,0,0,0,0,0,0,0,'Arrival of the courageous few? Mind your voice.',0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (95682,0,0,0,0,0,0,0,0,'Don\'t mind me snatching that right out of your hands.$B$BI recognized that orcish scrawl. So they\'re hoping to appease Rend? A fruitless and wasted effort.$B$BNo matter, this is highly valuable knowledge for the dark lady to consider.$B$BHere, I won\'t be taking any of this with me--and don\'t talk about the mission, grunt.',0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (96771,0,0,0,0,0,0,0,0,'Thank you, $C. You\'ve done me a great service, and rid the world of a traitorous cur.',0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (97130,0,0,0,0,0,0,0,0,'Thank you for recovering this. Lan\'dalock and I have long debated the nature of Gurubashi blood magic. An artifact such as this should be invaluable in helping us better understand this primal magic.',0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES (94981,0,0,0,0,'Have you gathered the materials?',0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES (95682,0,0,0,0,'We\'re here to get the important job done. If you can help, prove it.',0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES (96771,0,0,0,0,'Zalfan was once a very good friend, but he allowed himself to be seduced by promises of power offered by the Twilight\'s Hammer. This is unforgivable as far as I am concerned.$B$BThe world will not miss him.',0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES (97130,0,0,0,0,'Gurubashi blood magic is most distasteful, but still highly fascinating. Did you know that the ancient troll empires would periodically initiate a ritual known as the \"Blood Moon\" that would deliberately induce an insatiable madness and bloodlust on their entire population?$B$BWhy deliberately inflict a period of merciless bedlam and carnage on your people? To what end? It\'s deeply fascinating in an academic sense, but I shudder to think of how brutal life must have been in such a culture.',0);
