-- Six WoW Forever dungeon quests the server did not have at all:
--   94980 Krol'dok Moulding + 94981 Key Ingredients (Alliance, Krol'dok Compound Key 267089; 94980 starts from item 267138,
--         which Tunk 259256 drops in Krol'dok; both end at Alphonse Dumas 259250, Farholde Keep),
--   96771 Vengeance of the Highborne (Alliance, Ranath Nightstride 268425: kill Zalfan Moonshadow 268423 in Krol'dok),
--   97130 Ancient Gurubashi Secrets (Alliance, Archmage Timear 31439: the idol 276894 from Deathless Marrow 260202, Drowned City),
--   95663 Dragonmaw Rumors (Horde, Zaruk 2787 -> Deathstalker Agent 13155) + 95682 Open the Maw (Horde, Deathstalker Agent:
--         Dragonmaw Saboteur 275045 x2, Dragonmaw Warder 275044 x4, Dragonmaw Dispatch 284844 from Thaumaturgist 275046,
--         Excavation Site; rewards 271745, choice 271740 / 271732).
-- Source (read as data): Everlake's world data (buildthehomelab, GPL-3.0): 2026_11_14_950 build, 2026_11_16_900 texts,
--   2026_11_20_20 (94980) and 2026_11_20_30 (96771); there from Icy Veins' WoW Forever catalogue (players' addons on live),
--   EG Link and Questie (GPL-3.0). Checked against a WoW Forever fan database (giver/ender places, factions, rewards).
-- Ours, not Everlake's: 95663/95682 are Horde only (Everlake had every race; the fan database and the givers say Horde),
--   and the Alliance race mask of 94980/96771 is written exactly (Everlake's rows carry a rounded number).
-- Not in this file: the Deathstalker Agent and Zalfan Moonshadow have no spawn yet (their spots are measured on dev first).
-- Every item, NPC and drop these quests need is already in our data. Rows are deleted by key first: safe to run again.

DELETE FROM `quest_template` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_objectives` WHERE `QuestID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_classic_level` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_template_classic_level` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_classic_money` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_offer_reward` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `quest_request_items` WHERE `ID` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `creature_queststarter` WHERE `quest` IN (94980,94981,95663,95682,97130,96771);
DELETE FROM `creature_questender` WHERE `quest` IN (94980,94981,95663,95682,97130,96771);



